// Outer Heaven report webhook. Daily notify = Grok Watchdog / Grok chat.
// Do not require OpenClaw or Philanthropy. Do not wipe souls. Do not renumber Telegram topics.
const body = $json.body || $json;

const reportId = body.reportId || body.id || body.correlationId || `oh_${Date.now()}`;
const title = body.title || body.subject || 'Outer Heaven Report';
const status = body.status || 'info';
const content = body.content || body.message || body.report || '';
const source = body.source || 'outer-heaven';
const severity = body.severity || body.level || 'normal';

const text = [
  `OUTER HEAVEN REPORT`,
  ``,
  `Title: ${title}`,
  `Status: ${status}`,
  `Severity: ${severity}`,
  `Source: ${source}`,
  content ? `\nDetails:\n${content}` : '',
  ``,
  `ID: ${reportId}`,
  `Time: ${new Date().toISOString()}`,
  `Telegram optional. OpenClaw/Philanthropy HOLD.`
].filter(Boolean).join('\n');

return [{
  json: {
    text,
    reportId,
    title,
    severity,
    registerPayload: {
      correlationId: reportId,
      jobType: 'hive.outer_heaven.report',
      goal: title,
      source,
      status: status === 'info' ? 'done' : status,
      registerTo: 'scorpion',
      summary: content || title,
      metadata: {
        lane: 'hive-os',
        severity,
        telegramRequired: 'false',
        openclawHold: 'true',
        philanthropyHold: 'true'
      }
    }
  }
}];

// Telegram is LEGACY / optional. Missing token or 401 is not a workflow failure.
const token = $env.TELEGRAM_BOT_TOKEN;
const chatId = $env.HIVE_OUTER_HEAVEN_CHAT_ID || $env.HIVE_TELEGRAM_CHAT_ID;
if (!token || token === '' || token === 'undefined' || token === 'null' || !chatId) {
  return [{
    json: {
      sent: false,
      telegramReady: false,
      reportId: $json.reportId,
      error: 'Telegram hive report skipped (legacy). Daily notify is Grok Watchdog / Grok chat.',
      hint: 'Do not fail. Do not invent tokens. Do not renumber Telegram topics.'
    }
  }];
}
return [{
  json: {
    ...$json,
    telegramReady: true,
    _telegram: { token, chatId, ready: true }
  }
}];
